$empresaIdProd = 8;

foreach ($employees as $emp) {
    // Buscar si ya existe por email o numero_empleado
    $existing = User::where('email', $emp['email'])
        ->orWhere(function($q) use ($emp) {
            if (!empty($emp['numero_empleado'])) {
                $q->where('numero_empleado', $emp['numero_empleado']);
            }
        })->first();

