        if ($existing->id == 1) {
            echo "Usuario ID 1 (Admin) detectado. Solo activando flags de empleado.\n";
            $existing->update(['es_empleado' => true, 'puesto' => $emp['puesto'], 'departamento' => $emp['departamento']]);
        } else {
            $existing->update($data);
            echo "Empleado actualizado: {$emp['name']}\n";
